import XCTest

final class TapTestUITests: XCTestCase {
    func testOpenTeamStandup() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 5) {
            openButton.tap()
        }

        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        XCTAssertTrue(app.waitForExistence(timeout: 10))

        let teamStandup = app.staticTexts["Team Standup"]
        if teamStandup.waitForExistence(timeout: 10) {
            teamStandup.tap()
        }

        Thread.sleep(forTimeInterval: 3)
    }
}

import XCTest

final class TapTestUITests: XCTestCase {
    func testOpenTeamStandup() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 2) {
            openButton.tap()
        }

        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        XCTAssertTrue(app.waitForExistence(timeout: 10))

        let label = app.staticTexts["Team Standup"]
        XCTAssertTrue(label.waitForExistence(timeout: 10))
        label.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).tap()

        Thread.sleep(forTimeInterval: 3)
    }
}
